//! The catalogue's game database (lot GAMEHASH): what is known of a ROM image from its data CRC
//! (`builtin_patches::data_crc`, the No-Intro CRC), without loading it.
//!
//! Generated by `tools/gamedb_build.py` into `data/gamedb_roms.csv` and `data/gamedb_games.csv`,
//! turned into the tables below by `build.rs`: nothing is parsed at run time. A ROM is one image
//! (its No-Intro name, region and hashes); a game is the id the ROM images of a title share (the
//! Hackset metadata file name, `Blaster Master` for the USA, European and Japanese images) and
//! carries what goes with the whole title, as its built-in 3D profile.
//!
//! The database only says what Zaxnes knows of a ROM; what a feature does with it stays in that
//! feature's own table (`cartdb`, `builtin_patches`, `fceux_validated`), all keyed by the same
//! data CRC. What the list shows from here is provisional until the ROM is checked.

/// One ROM image.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Rom {
    /// CRC-32 of the PRG and CHR at the header's sizes.
    pub data_crc: u32,
    /// The game it is an image of.
    pub game: &'static str,
    /// Its No-Intro name, empty for an image No-Intro does not list (a homebrew).
    pub no_intro_name: &'static str,
    /// The No-Intro regions of the name, space-separated (`USA Europe`), empty when unknown.
    pub region: &'static str,
    /// MD5 of the same bytes as `data_crc`, lowercase hexadecimal; empty when unknown. It is the
    /// hash RetroAchievements knows the game by.
    pub data_md5: &'static str,
    /// The CRC-32 of whole files known to hold the image (header included), as an archive lists.
    pub file_crc32s: &'static [u32],
    /// The names of the 3dSen profiles made for this image only (a hack, one version of a game
    /// whose versions differ), before the game's (`profiles/3dsen_names.csv`). Usually empty.
    pub threedsen_profiles: &'static [&'static str],
}

/// One game.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Game {
    /// Its id, shared by its ROM images.
    pub id: &'static str,
    /// The file name of its built-in 3D profile (`rust/profiles`), empty for none.
    pub profile: &'static str,
    /// The names of its 3dSen profiles (the file name of a 3dSen profile without its extension,
    /// as 3dSen ships it; `profiles/3dsen_names.csv`), in that file's order.
    pub threedsen_profiles: &'static [&'static str],
}

/// A game RetroAchievements has achievements for (`data/ra_games.csv`, `tools/ra_game_list.py`),
/// by one of the hashes it accepts. Seen from the list before the server is asked: the study of
/// the ROM (`achievements::library`) has the last word.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RaGame {
    /// The hash, lowercase hexadecimal: `data_md5` of a clean dump.
    pub md5: &'static str,
    /// The game's id on the site.
    pub game_id: u32,
    /// `nes` or `fds`.
    pub console: &'static str,
    /// How many achievements it has.
    pub achievements: u32,
    /// How many points they are worth.
    pub points: u32,
    /// Its title on the site.
    pub title: &'static str,
}

mod tables {
    use super::{Game, RaGame, Rom};
    include!(concat!(env!("OUT_DIR"), "/gamedb-tables.rs"));
}

/// What a name is compared by: its letters and digits, in lowercase (as the profile list's name
/// rule, `ui::handheld::rom_list`).
#[must_use]
pub fn normalise(name: &str) -> String {
    name.chars()
        .filter(|character| character.is_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

/// The ROM image of data CRC `data_crc`.
#[must_use]
pub fn rom(data_crc: u32) -> Option<&'static Rom> {
    let at = tables::ROMS
        .binary_search_by_key(&data_crc, |rom| rom.data_crc)
        .ok()?;
    tables::ROMS.get(at)
}

/// The game of id `id` (exact).
#[must_use]
pub fn game(id: &str) -> Option<&'static Game> {
    let at = tables::GAMES
        .binary_search_by(|game| game.id.cmp(id))
        .ok()?;
    tables::GAMES.get(at)
}

/// The game of the ROM image of data CRC `data_crc`.
#[must_use]
pub fn game_of(data_crc: u32) -> Option<&'static Game> {
    game(rom(data_crc)?.game)
}

/// The built-in 3D profile of the ROM image of data CRC `data_crc`, through its game.
#[must_use]
pub fn profile_of(data_crc: u32) -> Option<&'static str> {
    Some(game_of(data_crc)?.profile).filter(|profile| !profile.is_empty())
}

/// The 3D profiles that suit the ROM image of data CRC `data_crc`, best first, by profile name
/// (a file name without its extension): the 3dSen profiles made for this image only, then its
/// game's built-in profile, then its game's 3dSen profiles. Empty for an unknown image: the list
/// then keeps its name rule.
#[must_use]
pub fn profile_names(data_crc: u32) -> Vec<&'static str> {
    let Some(rom) = rom(data_crc) else {
        return Vec::new();
    };
    let mut names: Vec<&'static str> = rom.threedsen_profiles.to_vec();
    if let Some(game) = game(rom.game) {
        if let Some(stem) = std::path::Path::new(game.profile)
            .file_stem()
            .and_then(|stem| stem.to_str())
        {
            names.push(stem);
        }
        names.extend_from_slice(game.threedsen_profiles);
    }
    names
}

/// The rows of a sorted `(key, rom index)` index whose key is `key`.
fn matches<K: Ord + Copy>(
    index: &'static [(K, u32)],
    key: K,
) -> impl Iterator<Item = &'static Rom> {
    let start = index.partition_point(|(entry, _)| *entry < key);
    index[start..]
        .iter()
        .take_while(move |(entry, _)| *entry == key)
        .filter_map(|(_, rom)| tables::ROMS.get(*rom as usize))
}

/// The ROM images of the game called `name`, compared [`normalise`]d.
pub fn roms_of_game(name: &str) -> impl Iterator<Item = &'static Rom> {
    let key = normalise(name);
    let start = tables::BY_GAME.partition_point(|(entry, _)| *entry < key.as_str());
    tables::BY_GAME[start..]
        .iter()
        .take_while(move |(entry, _)| *entry == key.as_str())
        .filter_map(|(_, rom)| tables::ROMS.get(*rom as usize))
}

/// The ROM images whose No-Intro name is `name`, compared [`normalise`]d (a file named after
/// No-Intro, `Blaster Master (USA).nes` without its extension, finds its image).
pub fn roms_named(name: &str) -> impl Iterator<Item = &'static Rom> {
    let key = normalise(name);
    let start = tables::BY_NO_INTRO_NAME.partition_point(|(entry, _)| *entry < key.as_str());
    tables::BY_NO_INTRO_NAME[start..]
        .iter()
        .take_while(move |(entry, _)| *entry == key.as_str())
        .filter_map(|(_, rom)| tables::ROMS.get(*rom as usize))
}

/// The ROM images a whole file of CRC-32 `file_crc32` is known to hold (what a `.7z` or `.zip`
/// lists, before anything is extracted).
pub fn roms_in_file(file_crc32: u32) -> impl Iterator<Item = &'static Rom> {
    matches(tables::BY_FILE_CRC32, file_crc32)
}

/// The RetroAchievements game of a ROM whose data MD5 is `md5` (lowercase hexadecimal), as the
/// list RetroAchievements gave when `ra_games.csv` was made.
#[must_use]
pub fn ra_game(md5: &str) -> Option<&'static RaGame> {
    let at = tables::RA_GAMES
        .binary_search_by(|game| game.md5.cmp(md5))
        .ok()?;
    tables::RA_GAMES.get(at)
}

/// Every ROM image, sorted by data CRC.
#[must_use]
pub fn roms() -> &'static [Rom] {
    tables::ROMS
}

/// Every game, sorted by id.
#[must_use]
pub fn games() -> &'static [Game] {
    tables::GAMES
}

#[cfg(test)]
mod tests {
    use super::*;

    const BLASTER_MASTER_USA: u32 = 0x3F0F_D764;

    #[test]
    fn a_rom_gives_its_image_and_its_game() {
        let rom = rom(BLASTER_MASTER_USA).unwrap();
        assert_eq!(
            (
                "Blaster Master",
                "Blaster Master (USA)",
                "USA",
                "12b0dbc4f2b22a50d0bb53c4929217f0"
            ),
            (rom.game, rom.no_intro_name, rom.region, rom.data_md5)
        );
        assert_eq!(&[0x52BC_F64A], rom.file_crc32s);
        assert_eq!(None, super::rom(0xFFFF_FFF1));
    }

    #[test]
    fn the_images_of_a_game_are_found_by_its_name() {
        let mut crcs: Vec<u32> = roms_of_game("blaster master")
            .map(|rom| rom.data_crc)
            .collect();
        crcs.sort_unstable();
        assert!(crcs.contains(&BLASTER_MASTER_USA), "{crcs:08X?}");
        assert!(crcs.contains(&0x8106_E694), "Europe");
        assert!(crcs.contains(&0x039B_4A9C), "Japan");
    }

    #[test]
    fn the_other_keys_find_the_same_image() {
        let named: Vec<u32> = roms_named("Blaster Master (USA)")
            .map(|rom| rom.data_crc)
            .collect();
        assert_eq!(vec![BLASTER_MASTER_USA], named);
        let in_file: Vec<u32> = roms_in_file(0x52BC_F64A).map(|rom| rom.data_crc).collect();
        assert_eq!(vec![BLASTER_MASTER_USA], in_file);
    }

    #[test]
    fn a_built_in_profile_goes_with_its_game() {
        let faxanadu = roms_of_game("Faxanadu").next().unwrap();
        assert_eq!(Some("Faxanadu.3dn"), profile_of(faxanadu.data_crc));
        assert_eq!(None, profile_of(BLASTER_MASTER_USA));
        assert_eq!(vec!["Faxanadu"], profile_names(faxanadu.data_crc));
        for game in games().iter().filter(|game| !game.profile.is_empty()) {
            assert!(
                crate::bundled_profiles::PROFILES
                    .iter()
                    .any(|(name, _)| *name == game.profile),
                "{} is not built in",
                game.profile
            );
        }
    }

    #[test]
    fn a_3dsen_profile_goes_with_its_game_or_only_with_its_images() {
        assert_eq!(
            vec!["Blaster Master (U)"],
            profile_names(BLASTER_MASTER_USA)
        );
        // The game Tetris has three 3dSen profiles, each for some of its images only.
        let tengen = roms_named("Tetris (USA) (Tengen) (Unl)").next().unwrap();
        assert_eq!(vec!["Tetris-Tengen"], profile_names(tengen.data_crc));
        let nintendo = roms_named("Tetris (USA)").next().unwrap();
        assert_eq!(vec!["Tetris-Nintendo"], profile_names(nintendo.data_crc));
        assert_eq!(0, game("Tetris").unwrap().threedsen_profiles.len());
        assert_eq!(0, profile_names(0xFFFF_FFF1).len());
        // A homebrew the Hackset does not know (profiles/extra_roms.csv): Chase, whose ROM 3dSen
        // 2.2 carries in its bundle.
        assert_eq!(vec!["Chase"], profile_names(0x331B_CC87));
        assert_eq!(vec!["zooming_secretary"], profile_names(0x6AA4_574C));
        assert_eq!(vec!["Depths"], profile_names(0x81B7_6AE6));
    }

    /// Every ROM a feature table names by data CRC is in the database, so that the list can show
    /// it as known.
    #[test]
    fn every_rom_a_feature_names_is_known() {
        for patch in zax_nes::builtin_patches::patches() {
            assert!(
                rom(patch.source_crc).is_some(),
                "{} {:08X}",
                patch.name,
                patch.source_crc
            );
        }
        for validated in crate::emulation::fceux_validated::all() {
            assert!(
                rom(validated.crc).is_some(),
                "{} {:08X}",
                validated.game,
                validated.crc
            );
        }
    }

    #[test]
    fn the_retroachievements_list_is_sorted_and_found() {
        assert!(tables::RA_GAMES
            .windows(2)
            .all(|pair| pair[0].md5 < pair[1].md5));
        for game in tables::RA_GAMES {
            assert_eq!(Some(game), ra_game(game.md5));
        }
        assert_eq!(None, ra_game("00000000000000000000000000000000"));
    }

    #[test]
    fn the_indexes_are_sorted_and_hold_every_image() {
        assert!(roms()
            .windows(2)
            .all(|pair| pair[0].data_crc < pair[1].data_crc));
        assert!(games().windows(2).all(|pair| pair[0].id < pair[1].id));
        assert_eq!(roms().len(), tables::BY_GAME.len());
        for (key, index) in tables::BY_GAME {
            assert_eq!(*key, normalise(roms()[*index as usize].game));
        }
        for (key, index) in tables::BY_NO_INTRO_NAME {
            assert_eq!(*key, normalise(roms()[*index as usize].no_intro_name));
        }
        assert!(roms().iter().all(|rom| game(rom.game).is_some()));
    }
}
